"""Offline, print-friendly evidence report generated from the validated summary."""
from html import escape
from pathlib import Path


def write_report(summary, destination):
    s = summary
    model_rows = ''.join(f"<tr><th>{escape(m['name'])}</th><td>{m['auc']:.4f}</td><td>{m['auc_ci'][0]:.4f}–{m['auc_ci'][1]:.4f}</td><td>{m['average_precision']:.4f}</td><td>{m['brier']:.4f}</td></tr>" for m in s['models'])
    stress_rows = ''.join(f"<tr><th>{r['scenario']}</th><td>{r['pd_multiplier']:.1f}×</td><td>+{r['lgd_add']:.0%}</td><td>{r['loss_rate']:.2%}</td></tr>" for r in s['stress'])
    sectors = sorted(s['sectors'], key=lambda x:x['exposure'], reverse=True)
    sector_rows = ''.join(f"<tr><th>{escape(r['sector'])}</th><td>{r['loans']:,}</td><td>{r['exposure']/s['exposure']:.2%}</td><td>{r['default_rate']:.2%}</td></tr>" for r in sectors)
    limitations = ''.join(f'<li>{escape(x)}</li>' for x in s['limitations'])
    html = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Credit risk — validated research | Ajai Upadhyaya</title><style>
    *{{box-sizing:border-box}}body{{max-width:1000px;margin:0 auto;padding:30px;color:#15201d;background:#fff;font:17px/1.65 Georgia,serif}}header,footer{{border-bottom:1px solid #abb8b1;padding:12px 0;display:flex;justify-content:space-between;font-size:14px;color:#506058}}h1{{font-size:52px;font-weight:400;line-height:1.1;letter-spacing:-2px;margin:45px 0 20px}}h2{{font-size:30px;font-weight:400;margin:36px 0 12px}}p{{max-width:850px}}.lede{{font-size:23px;color:#506058}}.stat{{display:flex;gap:40px;border-block:1px solid #c9d1cd;padding:20px 0;flex-wrap:wrap}}.stat strong{{font-size:33px;font-weight:400;color:#005c3e;display:block}}.stat span{{font:13px Arial,sans-serif}}table{{width:100%;border-collapse:collapse;font:14px/1.5 Arial,sans-serif}}th,td{{text-align:right;border-bottom:1px solid #d6dcd8;padding:12px 8px}}th:first-child{{text-align:left;font-weight:400}}thead th{{font-size:12px;color:#506058}}.scroll{{overflow:auto}}li{{margin:10px 0}}code{{font-size:12px;overflow-wrap:anywhere}}footer{{margin-top:40px;border-top:1px solid #abb8b1;border-bottom:0}}@media(max-width:600px){{body{{padding:20px}}h1{{font-size:39px}}.stat{{gap:24px}}.stat strong{{font-size:28px}}}}@media print{{body{{max-width:none}}h2{{break-after:avoid}}table{{break-inside:avoid}}}}
    </style></head><body><header><span>AJ / RESEARCH</span><span>Credit Observatory · Evidence report</span></header><main><h1>Credit prediction without the shortcuts.</h1><p class="lede">A reproducible experiment in default classification, portfolio concentration, and expected-loss sensitivity.</p><div class="stat"><div><strong>{s['rows']:,}</strong><span>Synthetic loans</span></div><div><strong>{s['test_rows']:,}</strong><span>Held-out observations</span></div><div><strong>{s['test_default_rate']:.2%}</strong><span>Holdout default frequency</span></div></div>
    <h2>Research question</h2><p>How much information about the supplied default outcome remains when outcome-adjacent fields and dataset-provided risk estimates are removed? The answer is evaluated on later origination cohorts, with all fitted preprocessing restricted to training data.</p>
    <h2>Design and validation</h2><p>Training: {s['train_rows']:,} loans originated before {s['cutoff']}. Holdout: {s['test_rows']:,} loans originated on or after that date. The models are prespecified; neither is selected or tuned using these results. The 95% AUC intervals use 200 bootstrap resamples of the same holdout.</p><p><strong>Feature allowlist:</strong> {escape(', '.join(s['features']))}.</p><p><strong>Excluded fields:</strong> {escape(', '.join(s['excluded']))}. The loan identifier, dates, and outcome flag are also excluded as predictors.</p>
    <div class="scroll"><table><thead><tr><th>Model</th><th>ROC AUC</th><th>95% interval</th><th>Avg. precision</th><th>Brier</th></tr></thead><tbody>{model_rows}</tbody></table></div><p>The constant training-prevalence predictor has Brier score {s['baseline_brier']:.4f}; lower is better. Average precision should be interpreted against holdout prevalence of {s['test_default_rate']:.2%}. These metrics describe synthetic classification, not investment performance.</p>
    <h2>Portfolio concentration</h2><div class="scroll"><table><thead><tr><th>Sector</th><th>Loans</th><th>Exposure share</th><th>Default frequency</th></tr></thead><tbody>{sector_rows}</tbody></table></div>
    <h2>Expected-loss sensitivity</h2><p>EL = Σ exposure × stressed annual PD × stressed LGD. These scenarios use the supplied synthetic annual PD and LGD, separately from the classifiers. Both risk inputs are capped at 100%. Shocks are assumptions, not calibrated forecasts.</p><div class="scroll"><table><thead><tr><th>Scenario</th><th>PD multiplier</th><th>LGD increment</th><th>EL / exposure</th></tr></thead><tbody>{stress_rows}</tbody></table></div>
    <h2>What this demonstrates</h2><p>Auditable feature selection, preprocessing isolated from the holdout, reproducible cohort partitioning, uncertainty reporting, and a clear separation between classification scores and annual expected loss. The modest results are more useful than near-perfect scores obtained from permissive feature sets.</p>
    <h2>Limits of the evidence</h2><ul>{limitations}</ul><p>{escape(s['source_attribution'])}</p>
    <h2>Reproduce the result</h2><p>Run <code>python run_analysis.py</code> from the creditrisk repository. Tests: <code>python -m pytest tests -q</code>. The summary JSON, holdout predictions, sector aggregates, and stress assumptions are generated in <code>outputs/validated/</code>.</p><p>Source SHA-256: <code>{s['source_sha256']}</code></p><p>Environment: <code>{escape(str(s['environment']))}</code></p><p>Method reference: <a href="https://scikit-learn.org/stable/common_pitfalls.html">scikit-learn — preventing preprocessing leakage</a>.</p></main><footer><span>Ajai Upadhyaya · Credit research</span><span>Synthetic research demonstration</span></footer></body></html>'''
    Path(destination).write_text(html)
